import polars as pl

df = pl.DataFrame({
    "a": [1, 5, 12, 7, 9],
    "b": [2, 8, 3, 4, 6],
})


def classify(row: dict) -> str:
    return "hi" if row["a"] + row["b"] > 10 else "lo"


df = df.with_columns(
    pl.struct(["a", "b"])
    .map_elements(classify, return_dtype=pl.String)
    .alias("label")
)

print(df)
